\label{lem:relative}
A nonexpansive map $H:Q(X)\to Q(X)$ fixing $e(X)$ pointwise is the
identity.

\label{lem:propagation}
If a nonexpansive $F:Q(X)\to Q(X)$ is an isometric embedding on
$e(X)$, then it is an isometric embedding on $Q(X)$.

\label{prop:linehull}
If $A\subseteq\mathbb R$ is unbounded above and below, then $Q(A,u|_A)$ is
isometric to $(\mathbb R,u)$, with the canonical copy corresponding to $A$.

\label{prop:integers}
The upper quasi-metric integers $(\mathbb Z,u)$ are bicomplete and $q$-plastic,
but their $q$-hyperconvex hull is not $q$-plastic.

\label{cor:rigidfailure}
There is a $q$-rigid $T_0$-quasi-metric space whose $q$-hyperconvex hull is
not $q$-plastic.

\label{prop:complements}
Suppose $(Q(X),D^s)$ is compact, its zero-distance order is a bounded
lattice, and $e(X)=C(Q(X))$. If $X$ is $q$-rigid, then $Q(X)$ is $q$-rigid.

\label{def:interval}
A $T_0$-quasi-metric space $(I,d)$ is a \emph{two-sided directed interval}
with distinct endpoints $a,b$ if, for every ordered pair $(x,y)$, at least
one equality holds:
\begin{align}
d(a,b)&=d(a,x)+d(x,y)+d(y,b),\label{eq:chainab}\\
d(b,a)&=d(b,x)+d(x,y)+d(y,a).\label{eq:chainba}
\end{align}

\label{thm:diameter}
If $(a,b)$ is the unique ordered diametral pair of a two-sided directed
interval $(I,d)$, then $I$ is $q$-rigid.
